import{_ as o,c as e,o as s,ag as r}from"./chunks/framework.Cycwnjj0.js";const a="/assets/custom-prducts-from-azonpress-dashboard.DtU-T_mS.webp",u="/assets/adding-multiple-custom-products.CzAdj9BH.webp",d="/assets/get-the-amazon-products-link.BKqXZ0LD.webp",p="/assets/open-desired-multiple-custom-products.BSWjAi-8.webp",n="/assets/edit_delete-button-of-a-specific-product.Dk9vCebt.webp",i="/assets/edit-product-popup-page.DukhPmLq.webp",c="/assets/preview-of-the-edited-product.DwCv17b-.webp",l="/assets/save-template-or-update-_-save-template-button.CEUSKOhq.webp",_=JSON.parse('{"title":"How to Add Multiple Custom Products","description":"","frontmatter":{},"headers":[],"relativePath":"guide/custom-product/how-to-add-multiple-custom-products.md","filePath":"guide/custom-product/how-to-add-multiple-custom-products.md"}'),m={name:"guide/custom-product/how-to-add-multiple-custom-products.md"};function h(g,t,w,b,f,y){return s(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="how-to-add-multiple-custom-products" tabindex="-1">How to Add Multiple Custom Products <a class="header-anchor" href="#how-to-add-multiple-custom-products" aria-label="Permalink to &quot;How to Add Multiple Custom Products&quot;">​</a></h1><p>AzonPress allows you to add Multiple Custom Products to your website as well. You can fetch the details of the product just by giving the product URL or you can add the product manually. With this feature, besides Amazon, you can also fetch data from other E-Commerce websites such as eBay and Etsy. This article guides you through <strong>Adding Multiple Custom Products</strong> with <strong>AzonPress</strong>.</p><h2 id="add-multiple-custom-products" tabindex="-1">Add Multiple Custom Products <a class="header-anchor" href="#add-multiple-custom-products" aria-label="Permalink to &quot;Add Multiple Custom Products&quot;">​</a></h2><p>To learn how to add multiple custom products, follow the steps with the screenshots below –</p><p>First, go to <strong>Custom Products</strong> from the <strong>WordPress Sidebar</strong> or <strong>AzonPress Navbar</strong>. Now, click the <strong>Add Custom Product</strong> button and a popup page will appear.</p><p><img src="'+a+'" alt="Custom Products from AzonPress Dashboard"></p><p>Now, select the <strong>Multiple Product Template</strong>, enter the <strong>Link</strong> of the <strong>Amazon products</strong> that you want to add under the <strong>URL</strong> field, and <strong>write any text as a Tracking ID</strong> so that you can find it later.</p><p>Once you are done, press the <strong>Continue</strong> button and your multiple custom products will be added.</p><p><img src="'+u+'" alt="Adding Multiple custom products"></p><h3 id="get-the-amazon-products-link" tabindex="-1">Get the Amazon Products Link <a class="header-anchor" href="#get-the-amazon-products-link" aria-label="Permalink to &quot;Get the Amazon Products Link&quot;">​</a></h3><p>To learn how to get the URL link of multiple Amazon products to fetch the product data into the website, follow the steps in the screenshot below –</p><p>First, go to your <strong>Amazon Associate account</strong>, <strong>search</strong> for the <strong>products</strong> you want to add, and copy the <strong>URL link</strong> from the address bar.</p><p><img src="'+d+'" alt="Get the Amazon Products link"></p><h2 id="edit-multiple-custom-products" tabindex="-1">Edit Multiple Custom Products <a class="header-anchor" href="#edit-multiple-custom-products" aria-label="Permalink to &quot;Edit Multiple Custom Products&quot;">​</a></h2><p>Multiple Custom Products allows you to <strong>Edit</strong> the details of each custom product individually e.g., Product Info, Image, and Product Rating.</p><p>To learn the details of the editor, follow the steps with screenshots below –</p><p>First, open your desired multiple custom products by clicking the <strong>Pencil Icon</strong>. You can also delete all the products by clicking the Delete button if needed.</p><p><img src="'+p+'" alt="Open desired Multiple custom products"></p><p>Now, select which product you want to edit or you can edit every product one by one.</p><p>To do this, just simply click the <strong>Edit</strong> button of a selected product and a popup page will appear where you will get all the options to edit your product.</p><p>You can also Delete an individual product by clicking the Delete button if needed.</p><p><img src="'+n+'" alt="Edit Delete button of a specific product"></p><p>Now, using the options below you can edit your custom products according to your needs.</p><p>Once you complete your edit click the <strong>Update</strong> button to save the changes and if not needed then simply press the <strong>Close</strong> button.</p><p><img src="'+i+'" alt="Edit Product popup page"></p><p>Here, you can see the Preview of the <strong>Edited</strong> custom product.</p><p><img src="'+c+'" alt="Preview of the edited product"></p><h2 id="customize-template-of-multiple-custom-products-with-settings" tabindex="-1">Customize Template of Multiple Custom Products with Settings <a class="header-anchor" href="#customize-template-of-multiple-custom-products-with-settings" aria-label="Permalink to &quot;Customize Template of Multiple Custom Products with Settings&quot;">​</a></h2><p>To learn how you can customize the template of your multiple custom products by using all the available settings options shown in the screenshot below, read this <a href="/guide/custom-product/settings-for-custom-products-template-customization.html">Documentation</a>.</p><p>Once you are done, click the <strong>Save Template</strong> or <strong>Update &amp; Save Template</strong> button to ensure all your edits, customization, and changes appear on your site.</p><p><img src="'+l+'" alt="Save Template or Update &amp; Save Template button"></p><p>This is how you can add and edit/customize your Multiple Custom Products!</p><p>If you have any further questions, concerns, or suggestions, please do not hesitate to contact our support team. Thank you.</p><hr>',34)])])}const C=o(m,[["render",h]]);export{_ as __pageData,C as default};
